          _hasValue = true;
        }
      },
      error: (err) => {
        if (!settled) {
          settled = true;
          signal?.removeEventListener('abort', abort);
          reject(err);
        }
      },
      complete: () => {
        if (!settled) {
          settled = true;
          signal?.removeEventListener('abort', abort);
          if (_hasValue) {
            resolve(_value);
          } else if (hasConfig) {
